from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
out=[]
for p in range(1,40):
 if p<=4: phase='A/B呈示'; items=[('A','A 公会主题：庄严步态与句首宣告；核对其节奏骨架与终止方向。'),('B','B 仪式性材料：铜管／圆号的宣告性重音与A区分；听加倍还是独立线。'),('H','C大调重心：检查低音支点、持续音与终止，而非只看响度。'),('O','配器：铜管重量与木管内层分开，避免把全体强奏听成单一声块。')]
 elif p<=12: phase='L/P抒情展开'; items=[('L','L 抒情材料：长线歌唱与延展句法；观察主线如何跨越伴奏层。'),('P','P 获奖歌关联片段：只标可辨的短语身份，不写成整首歌曲提前出现。'),('IM','接力模仿：比较相邻谱行的句首／节奏进入，区分模仿与齐奏加倍。'),('H','和声功能：局部主音化、低音方向、终止期待；减弱不等于终止。')]
 elif p<=18: phase='连接与积聚'; items=[('A→L','A→L 语气转化：公共性材料退场后，时间感由重音转向歌唱呼吸。'),('L/P','L与P并置：比较长句与短语的句法目标，避免把所有抒情线合成一个主题。'),('IM','模仿层：进入次序制造空间，后进入声部应听见而不覆盖先行线。'),('H','离心和声：变音可能是横向趋向音；须与低音和停留时间共同判断调域。')]
 elif p<=28: phase='A′谐谑发展'; items=[('A′','A′ 主题碎片化：庄严句首变成短促构件，身份保留而行为改变。'),('IM','fugato／模仿：记录进入先后、应答距离与声部接力；此处是模仿处理，不自动等于完整赋格。'),('CP','对位层：区分主题头、伴随节奏与填充和声；不同乐器齐奏不算多条主题。'),('O','发音配器：staccato、短促铜管与木管接入共同制造轻巧性，保持拍内稳定。')]
 elif p<=34: phase='复合对位'; items=[('A/B','A与B复合：比较两个公共性材料的重音位置和句尾方向，确认谁主导推进。'),('L/P','抒情层回返：长线材料作为上层或内声部，和短促活动层同时存在。'),('CP','自由多主题对位：记录独立线条、加倍线和低音骨架；不宣称严格三重可转位。'),('H','共同和声时间：不同主题共享重音／解决，和声把并行线条组织成整体。')]
 else: phase='综合与终结'; items=[('A′→A','A′回收为A：轻巧碎片重新获得庄严尺度，比较轮廓保留与表达改变。'),('A/B/L/P','主题综合：四类材料自由交织，按时间窗口听主线、应答、持续层和填充层。'),('CP','层级复原：先建立歌唱线与低音，再加入第二主题、活动层和铜管加倍。'),('H/O','C大调终结：和声重心与全乐队发音共同完成确认；高潮不是单纯加响。')]
 out.append({'page':p,'phase':phase,'items':[{'label':a,'text':t,'location':j} for j,(a,t) in enumerate(items)]})
(ROOT/'detailed_annotations.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf8')
print(len(out),sum(len(x['items']) for x in out))
